Item.method_code:
var viewId = this.getID();
var viewType = this.getProperty("type");

if (string.IsNullOrEmpty(viewType))
{
	var view = this.newItem("View", "get");
	view.setID(viewId);
	view.setAttribute("select", "type");
	var viewResult = view.apply();
	if (viewResult.isError())
	{
		return viewResult;
	}

	viewType = viewResult.getProperty("type");
}

this.setProperty("keyed_name", string.IsNullOrEmpty(viewType) == false ? $"{viewType}_{viewId}" : viewId);
return this;
